import { asset_categories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    categoriesAddition: Boolean
  },
  data() {
    return {
      categoriesName: "",
      depreciationCode: "",
      categoriesdescription: "",
      date: "",
      modal: false,
      isverification: false,
      loading: false,
      depreciationitems: Array.from({
        length: 100
      }, (_, i) => i + 1),
      categoryPrefix: ""
    };
  },
  watch: {
    categoriesAddition: {
      async handler() {
        this.categoryPrefix = "";
      },
      immediate: true
    }
  },
  // computed: {
  //   computedDateFormatted() {
  //     return this.formatDate(this.date);
  //   },
  //   verficationdaterule() {
  //     if (this.isverification == true) {
  //       return [(v) => !!v || "Required"];
  //     } else {
  //       return [];
  //     }
  //   },
  // },
  methods: {
    getcal() {
      this.modal = true;
    },
    fetch_category_name() {
      this.categoriesdescription = this.categoriesName;
    },
    convert_to_uppercase() {
      this.categoryPrefix = this.categoryPrefix.toUpperCase();
    },
    formatDate(date) {
      if (!date) return null;
      const [year, month, day] = date.split("-");
      return `${day}/${month}/${year}`;
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_categories, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "CREATE_CATEGORY",
            category_name: this.categoriesName,
            category_depriciation: this.depreciationCode == "" || this.depreciationCode == null ? "0" : this.depreciationCode.toString(),
            is_category_verification: this.isverification == null ? false : this.isverification,
            category_verification_date: this.isverification == true ? this.date : "",
            category_description: this.categoriesdescription,
            category_prefix: this.categoryPrefix
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.asset_categories);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("updaterefesh", "update");
          this.$refs.form.reset();
          this.categoryPrefix = "";
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
